reactions.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
const weapon = triggerData.weapon;
if (!weapon) return false;

const size = String(weapon.system?.size ?? "").toLowerCase();
const isHeavy = size === "heavy" || size === "superheavy";
const isMelee = /\bmelee\b/i.test(api.getWeaponType(weapon));

return isHeavy && isMelee && api.checkGate(reactorToken, "executioner_one"); }

reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {

    const choice = await api.askCard({
  title: "Backswing Cut",
  description: "Target a different enemy within threat?",
  yesText: "Use",
  noText: "Skip",
  owner: reactorToken,
  originToken: reactorToken,
  item
});
     if (!choice.confirmed) return;

    const hitIds = new Set(
    (triggerData.targets ?? []).map(entry => entry.target.id)
  );

  const candidates = canvas.tokens.placeables.filter(token =>
    token.actor &&
    token.id !== reactorToken.id &&
    !hitIds.has(token.id)
  );

  if (!candidates.length) return;
    const threat = await api.getMaxWeaponReach_WithBonus(triggerData.weapon)
    const target = await api.chooseToken(reactorToken, {
        title: "Select Token",
        range: threat,
        includeSelf: false,
        count: 1,
		selection: candidates,
    });
    if (!target?.[0]) return;


    if (!await api.consumeOncePerRound(
      reactorToken,
      "executioner_one"
    )) return;

    await api.beginWeaponAttackFlow(triggerData.weapon, {
        targets: target
        }, {flow_bonus: [{
      id: foundry.utils.randomID(),
      name: "Backswing Cut",
      type: "target_modifier",
      subtype: "half_damage"
    }]})
}

reactions.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
const weapon = triggerData.weapon;
if (!weapon) return false;

const size = String(weapon.system?.size ?? "").toLowerCase();
const isHeavy = size === "heavy" || size === "superheavy";
const isMelee = /\bmelee\b/i.test(api.getWeaponType(weapon));
const critTargets = (triggerData.targets ?? [])
  .filter(entry => entry.crit)
  .map(entry => entry.target);

if (!critTargets.length) return false;

return isHeavy && isMelee && api.checkGate(reactorToken, "executioner_two"); }

